create table readings (id bigint generated always as identity primary key, org_id integer not null, taken_at timestamptz not null);
create index on readings (taken_at);
create index on readings (org_id);
insert into readings (org_id, taken_at) values (1, '2026-06-30 23:10:00+00');

-- The schema of the functions that keep rollups and refresh time rollups.
create schema if not exists "rollups";

-- The table and refresh function of a time rollup of readings_hourly.
create table "public"."readings_hourly" as select date_trunc('hour', c."taken_at"::timestamptz) as "bucket", c."org_id" as "org_id", count(*) as "events" from "public"."readings" as c group by 1, 2 with no data;
alter table "public"."readings_hourly" add column "id" bigint generated always as identity primary key, alter column "bucket" set not null, alter column "org_id" set not null, alter column "events" set not null;
create unique index "readings_hourly_bucket_key" on "public"."readings_hourly" ("bucket", "org_id");
create index "readings_hourly_org_id_bucket" on "public"."readings_hourly" ("org_id", "bucket");
comment on table "public"."readings_hourly" is 'protobase time rollup: from "public"."readings" (taken_at timestamp, org_id integer)';
create or replace function "rollups"."readings_hourly_refresh"("from" timestamptz) returns void language plpgsql set search_path = pg_catalog, pg_temp set timezone = 'UTC' as $buckets$
<<refresh>>
declare
  since "public"."readings"."taken_at"%type := date_trunc('hour', $1);
begin
with fresh as (
  select date_trunc('hour', c."taken_at"::timestamptz) as "bucket", c."org_id" as "org_id", count(*) as "events"
  from "public"."readings" as c
  where c."taken_at" >= refresh.since
  group by 1, 2
), gone as (
  delete from "public"."readings_hourly" as r where r."bucket" >= date_trunc('hour', $1) and not exists (select from fresh where fresh."bucket" = r."bucket" and fresh."org_id" = r."org_id")
)
insert into "public"."readings_hourly" ("bucket", "org_id", "events")
select "bucket", "org_id", "events" from fresh
on conflict ("bucket", "org_id") do update set "events" = excluded."events";
end
$buckets$;

-- The table and refresh function of a time rollup of readings_hourly.
select "rollups"."readings_hourly_refresh"('-infinity');
